SELECT sm.store_nm AS store_nm, '' AS user_name, CAST(NULL AS VARCHAR(100)) AS user_id, am.act_dt AS act_dt, COUNT(am.act_idx) AS cnt FROM store_mst sm LEFT OUTER JOIN active_mst am ON sm.store_idx = am.store_idx AND (am.appr_status = 'PENDING' OR am.appr_status = 'APPROVED') AND am.act_dt BETWEEN #{startDt} AND #{endDt} WHERE 1 = 1
AND sm.brand_cd = #{brandCd}
GROUP BY sm.store_nm, am.act_dt ORDER BY sm.store_nm, am.act_dt

SELECT user_id, user_name FROM user_mst
WHERE user_id IN

    #{id}

SELECT c.chk_idx, c.brand_cd, c.chk_type, COALESCE(cm.code_nm, c.chk_type) AS chk_type_nm, c.chk_content, c.base_score, c.use_yn, c.display_order FROM chk_mst c LEFT JOIN code_mst cm ON cm.grp_cd = '50' AND cm.code_cd = c.chk_type WHERE 1 = 1
AND c.brand_cd = #{brandCd}
AND c.chk_type = #{chkType}
ORDER BY c.chk_type

SELECT

FROM active_mst am



            am.appr_status != 'DRAFT'


            am.appr_status = #{q.apprStatus}


            am.store_idx = #{q.storeIdx}


            () = #{q.chkYn, jdbcType=CHAR}


            am.sv_id = #{q.svId}
            AND TRIM(COALESCE(am.appr_notes, '')) <> ''
            AND UPPER(TRIM(COALESCE(am.appr_status, ''))) <> 'PENDING'





        ORDER BY am.act_dt DESC, am.act_idx DESC


        ORDER BY am.create_dt DESC, am.act_idx DESC

SELECT COUNT(*)
FROM notif_mst nm
         INNER JOIN active_mst am ON

WHERE nm.act_idx = #{actIdx}
  AND nm.user_id = #{userId}
  AND nm.notif_typ = #{notifTyp}

SELECT COUNT(*)
FROM notif_mst nm
         INNER JOIN active_mst am ON

WHERE nm.act_idx = #{actIdx}
  AND nm.user_id = #{userId}
  AND nm.notif_typ = #{notifTyp}
  AND (
    nm.appr_yn IS NULL
    OR TRIM(nm.appr_yn) = ''
    OR UPPER(TRIM(nm.appr_yn)) = 'N'
)

mapper.update:
UPDATE notif_mst nm
SET appr_yn = #{apprYn}
WHERE nm.act_idx = #{actIdx}
  AND nm.user_id = #{userId}
  AND nm.notif_typ = #{notifTyp}
  AND (
    nm.appr_yn IS NULL
    OR TRIM(nm.appr_yn) = ''
    OR UPPER(TRIM(nm.appr_yn)) = 'N'
)
  AND EXISTS (
    SELECT 1
    FROM active_mst am
    WHERE am.act_idx = nm.act_idx
      AND (
        TRIM(COALESCE(am.appr_id, '')) = TRIM(nm.user_id)
        OR CONCAT(',', REPLACE(TRIM(COALESCE(am.appr_id, '')), ' ', ''), ',')
           LIKE CONCAT('%,', TRIM(nm.user_id), ',%')
      )
)

